import{_ as t,o as i,c as n,ah as r}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Rechtlicher Hinweis & Satire-Disclaimer","description":"","frontmatter":{},"headers":[],"relativePath":"disclaimer.md","filePath":"disclaimer.md"}'),a={name:"disclaimer.md"};function s(o,e,l,c,h,u){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="rechtlicher-hinweis-satire-disclaimer" tabindex="-1">Rechtlicher Hinweis &amp; Satire-Disclaimer <a class="header-anchor" href="#rechtlicher-hinweis-satire-disclaimer" aria-label="Permalink to &quot;Rechtlicher Hinweis &amp; Satire-Disclaimer&quot;">​</a></h1><h2 id="_1-natur-des-projekts" tabindex="-1">1. Natur des Projekts <a class="header-anchor" href="#_1-natur-des-projekts" aria-label="Permalink to &quot;1. Natur des Projekts&quot;">​</a></h2><p>„Das Horten-Mysterium“ ist ein <strong>künstlerisches Projekt</strong> im Genre der <strong>Mockumentary</strong>. Es handelt sich um eine fiktive, satirische Auseinandersetzung mit Themen der Zeitgeschichte, Wirtschaft und Politik.</p><h2 id="_2-unterscheidung-zwischen-fakten-und-fiktion" tabindex="-1">2. Unterscheidung zwischen Fakten und Fiktion <a class="header-anchor" href="#_2-unterscheidung-zwischen-fakten-und-fiktion" aria-label="Permalink to &quot;2. Unterscheidung zwischen Fakten und Fiktion&quot;">​</a></h2><p>Um die rechtliche Integrität zu wahren, ist das Projekt in zwei klar getrennte Bereiche unterteilt:</p><ul><li><strong>Sektion „Recherche“:</strong> Diese Sektion basiert auf öffentlich zugänglichen Quellen, Medienberichten, wissenschaftlichen Gutachten (z.B. Hoeres-Gutachten 2022) und offiziellen Gerichts- oder Untersuchungsausschuss-Akten. Wir bemühen uns um höchste Sorgfalt, übernehmen jedoch keine Gewähr für die Aktualität oder Vollständigkeit der externen Quellen.</li><li><strong>Sektionen „Drehbuch“ &amp; „Hörbuch“:</strong> Sämtliche hier dargestellten Dialoge, Szenen und Handlungsabläufe sind <strong>frei erfunden</strong>. Sie dienen der satirischen Überspitzung und künstlerischen Interpretation. Ähnlichkeiten mit lebenden oder verstorbenen Personen in diesen Sektionen sind – sofern sie über den allgemein bekannten öffentlichen Kontext hinausgehen – rein zufällig oder als satirische Rollenbilder zu verstehen.</li></ul><h2 id="_3-visuelle-gestaltung-„geleakt-stempel" tabindex="-1">3. Visuelle Gestaltung („Geleakt“-Stempel) <a class="header-anchor" href="#_3-visuelle-gestaltung-„geleakt-stempel" aria-label="Permalink to &quot;3. Visuelle Gestaltung („Geleakt“-Stempel)&quot;">​</a></h2><p>Sämtliche als „GELEAKT“ oder „VERTRAULICH“ gekennzeichneten Grafiken auf dieser Webseite sind <strong>künstlerische Stilmittel</strong>. Sie dienen der atmosphärischen Untermalung des Mockumentary-Konzepts und stellen keine echten, unrechtmäßig erlangten Regierungsdokumente oder Geheimakten dar.</p><h2 id="_4-einsatz-von-kunstlicher-intelligenz" tabindex="-1">4. Einsatz von Künstlicher Intelligenz <a class="header-anchor" href="#_4-einsatz-von-kunstlicher-intelligenz" aria-label="Permalink to &quot;4. Einsatz von Künstlicher Intelligenz&quot;">​</a></h2><p>Dieses Projekt wurde unter Mitwirkung von KI-Systemen (Gemini CLI, Grok) erstellt. Die KIs fungieren als kreative Werkzeuge zur Strukturierung von Daten und zur Generierung von satirischen Texten. Die finale redaktionelle Verantwortung und die Entscheidung über die Veröffentlichung liegen beim Projektleiter.</p><hr><h1 id="legal-notice-satire-disclaimer-english" tabindex="-1">Legal Notice &amp; Satire Disclaimer (English) <a class="header-anchor" href="#legal-notice-satire-disclaimer-english" aria-label="Permalink to &quot;Legal Notice &amp; Satire Disclaimer (English)&quot;">​</a></h1><h2 id="_1-nature-of-the-project" tabindex="-1">1. Nature of the Project <a class="header-anchor" href="#_1-nature-of-the-project" aria-label="Permalink to &quot;1. Nature of the Project&quot;">​</a></h2><p>&quot;The Horten Mystery&quot; is an <strong>artistic project</strong> in the genre of <strong>Mockumentary</strong>. It is a fictional, satirical examination of contemporary history, economics, and politics.</p><h2 id="_2-distinction-between-fact-and-fiction" tabindex="-1">2. Distinction between Fact and Fiction <a class="header-anchor" href="#_2-distinction-between-fact-and-fiction" aria-label="Permalink to &quot;2. Distinction between Fact and Fiction&quot;">​</a></h2><p>To maintain legal integrity, the project is divided into two clearly separated areas:</p><ul><li><strong>&quot;Research&quot; Section:</strong> This section is based on publicly accessible sources, media reports, scientific reports, and official court or inquiry committee files.</li><li><strong>&quot;Screenplay&quot; &amp; &quot;Audiobook&quot; Sections:</strong> All dialogues, scenes, and sequences of events presented here are <strong>fictional</strong>. They serve the purpose of satirical exaggeration and artistic interpretation.</li></ul><h2 id="_3-visual-design-leaked-stamp" tabindex="-1">3. Visual Design (&quot;Leaked&quot; Stamp) <a class="header-anchor" href="#_3-visual-design-leaked-stamp" aria-label="Permalink to &quot;3. Visual Design (&quot;Leaked&quot; Stamp)&quot;">​</a></h2><p>All graphics marked as &quot;LEAKED&quot; or &quot;CONFIDENTIAL&quot; on this website are <strong>artistic stylistic devices</strong>. They are intended to enhance the atmosphere of the mockumentary concept and do not represent genuine, unlawfully obtained government documents.</p>',19)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
